insert into private.levelup_questions(id,idx,question,answer) values ('q5',5,'{"subject":"office","title":{"en":"Word: structure a document","uz":"Word: hujjatni tartiblash","ru":"Word: структура документа"},"lesson":{"en":"Heading styles describe document structure. Heading 1 is for a main section heading; normal text is for paragraphs. Styles help readers and screen readers navigate your work.","uz":"Sarlavha uslublari hujjat tuzilishini belgilaydi. Heading 1 asosiy bo‘lim sarlavhasi uchun, oddiy matn esa abzatslar uchun. Uslublar hujjatni o‘qish va unda yurishni osonlashtiradi.","ru":"Стили заголовков задают структуру документа. Заголовок 1 подходит для основного раздела, обычный текст — для абзацев. Стили помогают читателям ориентироваться."},"prompt":{"en":"Choose the style for a main section heading.","uz":"Asosiy bo‘lim sarlavhasi uchun uslubni tanla.","ru":"Выбери стиль для заголовка основного раздела."},"options":[{"value":"normal","label":{"en":"Normal text","uz":"Oddiy matn","ru":"Обычный текст"}},{"value":"heading","label":{"en":"Heading 1","uz":"Sarlavha 1","ru":"Заголовок 1"}},{"value":"caption","label":{"en":"Caption","uz":"Izoh","ru":"Подпись"}}]}'::jsonb,'heading') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
