insert into private.levelup_questions(id,idx,question,answer) values ('q9',9,'{"subject":"office","title":{"en":"PowerPoint: entrance effects","uz":"PowerPoint: kirish effektlari","ru":"PowerPoint: эффекты входа"},"lesson":{"en":"An entrance animation makes an object appear. Fly In brings it onto the slide. Disappear and Fade Out are exit effects. A short entrance can draw attention without distracting from your message.","uz":"Kirish animatsiyasi obyektni ko‘rsatadi. Fly In uni slaydga olib kiradi. Disappear va Fade Out esa chiqish effektlari. Qisqa kirish effekti asosiy fikrga e’tibor qaratadi.","ru":"Анимация входа показывает объект. Fly In выводит его на слайд. Disappear и Fade Out — эффекты выхода. Короткий эффект входа помогает выделить главную мысль."},"prompt":{"en":"Which effect brings an object onto the slide?","uz":"Qaysi effekt obyektni slaydga olib kiradi?","ru":"Какой эффект выводит объект на слайд?"},"options":[{"value":"fly","label":{"en":"Fly In","uz":"Fly In — uchib kirish","ru":"Fly In — появление"}},{"value":"disappear","label":{"en":"Disappear","uz":"Yo‘qolish","ru":"Исчезновение"}},{"value":"fade","label":{"en":"Fade Out","uz":"So‘nib chiqish","ru":"Затухание"}}]}'::jsonb,'fly') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
insert into private.levelup_questions(id,idx,question,answer) values ('q10',10,'{"subject":"math","title":{"en":"Functions: find a point","uz":"Funksiya: nuqtani topish","ru":"Функции: найди точку"},"lesson":{"en":"To find y, replace x with the given number. For y = 2x + 3 and x = 2, y = 2 × 2 + 3 = 7. In x², multiply x by itself. Explore your equation in Desmos, then calculate your own point.","uz":"y ni topish uchun x o‘rniga berilgan sonni qo‘y. y = 2x + 3 va x = 2 bo‘lsa, y = 2 × 2 + 3 = 7. x² da x ni o‘ziga ko‘paytir. Tenglamani Desmosda tekshirib, nuqtani o‘zing hisobla.","ru":"Чтобы найти y, подставь число вместо x. При y = 2x + 3 и x = 2 получим y = 2 × 2 + 3 = 7. x² означает x, умноженный на себя. Исследуй уравнение в Desmos и вычисли свою точку."},"prompt":{"en":"For y = 4x + 3, find y when x = 4.","uz":"y = 4x + 3 bo‘lsa, x = 4 da y ni top.","ru":"Для y = 4x + 3 найди y при x = 4."},"input":"number","graph":true}'::jsonb,'19') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
