insert into private.levelup_questions(id,idx,question,answer) values ('q12',12,'{"subject":"coding","title":{"en":"Windows shortcuts","uz":"Windows tugmalari","ru":"Сочетания Windows"},"lesson":{"en":"A shortcut combines keys to perform an action. Windows + E opens File Explorer. Windows + L locks your computer. Lock a shared school PC before leaving it.","uz":"Tugmalar birikmasi amalni tez bajaradi. Windows + E fayl boshqaruvchisini ochadi. Windows + L kompyuterni qulflaydi. Umumiy kompyuterdan ketayotganda uni qulflashni unutma.","ru":"Сочетание клавиш быстро выполняет действие. Windows + E открывает Проводник. Windows + L блокирует компьютер. Уходя от общего компьютера, блокируй его."},"prompt":{"en":"Which shortcut opens File Explorer?","uz":"Fayl boshqaruvchisini qaysi birikma ochadi?","ru":"Как открыть Проводник?"},"options":[{"value":"explorer","label":{"en":"Windows + E","uz":"Windows + E","ru":"Windows + E"}},{"value":"lock","label":{"en":"Windows + L","uz":"Windows + L","ru":"Windows + L"}},{"value":"print","label":{"en":"Ctrl + P","uz":"Ctrl + P","ru":"Ctrl + P"}}]}'::jsonb,'explorer') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
insert into private.levelup_questions(id,idx,question,answer) values ('q13',13,'{"subject":"office","title":{"en":"Excel: add a range","uz":"Excel: oraliqni qo‘shish","ru":"Excel: сумма диапазона"},"lesson":{"en":"A formula starts with =. SUM adds a range. A colon means “through”: A1:A3 includes A1, A2, and A3. Try naming a range on paper, then write its SUM formula.","uz":"Formula = belgisi bilan boshlanadi. SUM oraliqdagi sonlarni qo‘shadi. A1:A3 yozuvi A1, A2 va A3 ni bildiradi. Oraliqni tasavvur qilib, SUM formulasini yoz.","ru":"Формула начинается с =. SUM складывает диапазон. Двоеточие означает «до»: A1:A3 включает A1, A2 и A3. Назови ячейки диапазона, затем запиши формулу SUM."},"prompt":{"en":"Write a SUM formula for B1 through B4.","uz":"B1 dan B4 gacha bo‘lgan oraliq uchun SUM formulasini yoz.","ru":"Запиши формулу SUM для диапазона от B1 до B4."},"input":"formula"}'::jsonb,'=SUM(B1:B4)') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
insert into private.levelup_questions(id,idx,question,answer) values ('q14',14,'{"subject":"math","title":{"en":"Functions: find a point","uz":"Funksiya: nuqtani topish","ru":"Функции: найди точку"},"lesson":{"en":"To find y, replace x with the given number. For y = 2x + 3 and x = 2, y = 2 × 2 + 3 = 7. In x², multiply x by itself. Explore your equation in Desmos, then calculate your own point.","uz":"y ni topish uchun x o‘rniga berilgan sonni qo‘y. y = 2x + 3 va x = 2 bo‘lsa, y = 2 × 2 + 3 = 7. x² da x ni o‘ziga ko‘paytir. Tenglamani Desmosda tekshirib, nuqtani o‘zing hisobla.","ru":"Чтобы найти y, подставь число вместо x. При y = 2x + 3 и x = 2 получим y = 2 × 2 + 3 = 7. x² означает x, умноженный на себя. Исследуй уравнение в Desmos и вычисли свою точку."},"prompt":{"en":"For y = x² − 4, find y when x = 5.","uz":"y = x² − 4 bo‘lsa, x = 5 da y ni top.","ru":"Для y = x² − 4 найди y при x = 5."},"input":"number","graph":true}'::jsonb,'21') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
insert into private.levelup_questions(id,idx,question,answer) values ('q15',15,'{"subject":"typing","title":{"en":"Keyboard fluency","uz":"Klaviaturadan ravon foydalanish","ru":"Уверенная работа с клавиатурой"},"lesson":{"en":"Accuracy comes before speed. Sit comfortably, keep your wrists relaxed, and look at the task rather than rushing. Ctrl + S saves; Ctrl + C copies; Ctrl + Z undoes; Ctrl + V pastes. Practise finding those keys without looking.","uz":"Avval aniqlik, keyin tezlik. Qulay o‘tir, bilaklaringni bo‘sh tut, shoshilma. Ctrl + S saqlaydi, Ctrl + C nusxalaydi, Ctrl + Z oxirgi amalni bekor qiladi, Ctrl + V joylashtiradi. Tugmalarni qaramasdan topishga urin.","ru":"Сначала точность, потом скорость. Сядь удобно, расслабь запястья, не спеши. Ctrl + S сохраняет, Ctrl + C копирует, Ctrl + Z отменяет, Ctrl + V вставляет. Попробуй находить эти клавиши, не глядя."},"prompt":{"en":"Type the shortcut to paste. Example format: Ctrl + S","uz":"joylashtirish uchun tugmalar birikmasini yoz. Namuna: Ctrl + S","ru":"Напечатай сочетание для действия «вставить». Формат: Ctrl + S"},"input":"shortcut"}'::jsonb,'CTRL+V') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
insert into private.levelup_questions(id,idx,question,answer) values ('q16',16,'{"subject":"coding","title":{"en":"Read a little code","uz":"Kichik kodni tushun","ru":"Прочитай немного кода"},"lesson":{"en":"A variable stores a value. + adds values; * multiplies them. print, std::cout, and Console.WriteLine show the result in Python, C++, and C#. Work through the expression before running it.","uz":"O‘zgaruvchi qiymatni saqlaydi. + qo‘shadi, * ko‘paytiradi. Python, C++ va C# da print, std::cout va Console.WriteLine natijani ko‘rsatadi. Kodni ishga tushirishdan oldin hisoblab ko‘r.","ru":"Переменная хранит значение. + складывает, * умножает. print, std::cout и Console.WriteLine выводят результат в Python, C++ и C#. Сначала вычисли выражение самостоятельно."},"prompt":{"en":"What does this code print?","uz":"Bu kod qanday natija chiqaradi?","ru":"Что выведет этот код?"},"code":"int gems = 10;\nstd::cout << gems + 8;","input":"number"}'::jsonb,'18') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
insert into private.levelup_questions(id,idx,question,answer) values ('q17',17,'{"subject":"office","title":{"en":"Word: structure a document","uz":"Word: hujjatni tartiblash","ru":"Word: структура документа"},"lesson":{"en":"Heading styles describe document structure. Heading 1 is for a main section heading; normal text is for paragraphs. Styles help readers and screen readers navigate your work.","uz":"Sarlavha uslublari hujjat tuzilishini belgilaydi. Heading 1 asosiy bo‘lim sarlavhasi uchun, oddiy matn esa abzatslar uchun. Uslublar hujjatni o‘qish va unda yurishni osonlashtiradi.","ru":"Стили заголовков задают структуру документа. Заголовок 1 подходит для основного раздела, обычный текст — для абзацев. Стили помогают читателям ориентироваться."},"prompt":{"en":"Choose the style for a main section heading.","uz":"Asosiy bo‘lim sarlavhasi uchun uslubni tanla.","ru":"Выбери стиль для заголовка основного раздела."},"options":[{"value":"normal","label":{"en":"Normal text","uz":"Oddiy matn","ru":"Обычный текст"}},{"value":"heading","label":{"en":"Heading 1","uz":"Sarlavha 1","ru":"Заголовок 1"}},{"value":"caption","label":{"en":"Caption","uz":"Izoh","ru":"Подпись"}}]}'::jsonb,'heading') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
insert into private.levelup_questions(id,idx,question,answer) values ('q18',18,'{"subject":"math","title":{"en":"Functions: find a point","uz":"Funksiya: nuqtani topish","ru":"Функции: найди точку"},"lesson":{"en":"To find y, replace x with the given number. For y = 2x + 3 and x = 2, y = 2 × 2 + 3 = 7. In x², multiply x by itself. Explore your equation in Desmos, then calculate your own point.","uz":"y ni topish uchun x o‘rniga berilgan sonni qo‘y. y = 2x + 3 va x = 2 bo‘lsa, y = 2 × 2 + 3 = 7. x² da x ni o‘ziga ko‘paytir. Tenglamani Desmosda tekshirib, nuqtani o‘zing hisobla.","ru":"Чтобы найти y, подставь число вместо x. При y = 2x + 3 и x = 2 получим y = 2 × 2 + 3 = 7. x² означает x, умноженный на себя. Исследуй уравнение в Desmos и вычисли свою точку."},"prompt":{"en":"For y = 3x + 5, find y when x = 6.","uz":"y = 3x + 5 bo‘lsa, x = 6 da y ni top.","ru":"Для y = 3x + 5 найди y при x = 6."},"input":"number","graph":true}'::jsonb,'23') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
