insert into private.levelup_questions(id,idx,question,answer) values ('q20',20,'{"subject":"coding","title":{"en":"Read a little code","uz":"Kichik kodni tushun","ru":"Прочитай немного кода"},"lesson":{"en":"A variable stores a value. + adds values; * multiplies them. print, std::cout, and Console.WriteLine show the result in Python, C++, and C#. Work through the expression before running it.","uz":"O‘zgaruvchi qiymatni saqlaydi. + qo‘shadi, * ko‘paytiradi. Python, C++ va C# da print, std::cout va Console.WriteLine natijani ko‘rsatadi. Kodni ishga tushirishdan oldin hisoblab ko‘r.","ru":"Переменная хранит значение. + складывает, * умножает. print, std::cout и Console.WriteLine выводят результат в Python, C++ и C#. Сначала вычисли выражение самостоятельно."},"prompt":{"en":"What does this code print?","uz":"Bu kod qanday natija chiqaradi?","ru":"Что выведет этот код?"},"code":"int energy = 11;\nConsole.WriteLine(energy * 9);","input":"number"}'::jsonb,'99') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
insert into private.levelup_questions(id,idx,question,answer) values ('q21',21,'{"subject":"office","title":{"en":"PowerPoint: entrance effects","uz":"PowerPoint: kirish effektlari","ru":"PowerPoint: эффекты входа"},"lesson":{"en":"An entrance animation makes an object appear. Fly In brings it onto the slide. Disappear and Fade Out are exit effects. A short entrance can draw attention without distracting from your message.","uz":"Kirish animatsiyasi obyektni ko‘rsatadi. Fly In uni slaydga olib kiradi. Disappear va Fade Out esa chiqish effektlari. Qisqa kirish effekti asosiy fikrga e’tibor qaratadi.","ru":"Анимация входа показывает объект. Fly In выводит его на слайд. Disappear и Fade Out — эффекты выхода. Короткий эффект входа помогает выделить главную мысль."},"prompt":{"en":"Which effect brings an object onto the slide?","uz":"Qaysi effekt obyektni slaydga olib kiradi?","ru":"Какой эффект выводит объект на слайд?"},"options":[{"value":"fly","label":{"en":"Fly In","uz":"Fly In — uchib kirish","ru":"Fly In — появление"}},{"value":"disappear","label":{"en":"Disappear","uz":"Yo‘qolish","ru":"Исчезновение"}},{"value":"fade","label":{"en":"Fade Out","uz":"So‘nib chiqish","ru":"Затухание"}}]}'::jsonb,'fly') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
