insert into private.levelup_questions(id,idx,question,answer) values ('q25',25,'{"subject":"office","title":{"en":"Excel: add a range","uz":"Excel: oraliqni qo‘shish","ru":"Excel: сумма диапазона"},"lesson":{"en":"A formula starts with =. SUM adds a range. A colon means “through”: A1:A3 includes A1, A2, and A3. Try naming a range on paper, then write its SUM formula.","uz":"Formula = belgisi bilan boshlanadi. SUM oraliqdagi sonlarni qo‘shadi. A1:A3 yozuvi A1, A2 va A3 ni bildiradi. Oraliqni tasavvur qilib, SUM formulasini yoz.","ru":"Формула начинается с =. SUM складывает диапазон. Двоеточие означает «до»: A1:A3 включает A1, A2 и A3. Назови ячейки диапазона, затем запиши формулу SUM."},"prompt":{"en":"Write a SUM formula for A1 through A3.","uz":"A1 dan A3 gacha bo‘lgan oraliq uchun SUM formulasini yoz.","ru":"Запиши формулу SUM для диапазона от A1 до A3."},"input":"formula"}'::jsonb,'=SUM(A1:A3)') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
insert into private.levelup_questions(id,idx,question,answer) values ('q26',26,'{"subject":"math","title":{"en":"Functions: find a point","uz":"Funksiya: nuqtani topish","ru":"Функции: найди точку"},"lesson":{"en":"To find y, replace x with the given number. For y = 2x + 3 and x = 2, y = 2 × 2 + 3 = 7. In x², multiply x by itself. Explore your equation in Desmos, then calculate your own point.","uz":"y ni topish uchun x o‘rniga berilgan sonni qo‘y. y = 2x + 3 va x = 2 bo‘lsa, y = 2 × 2 + 3 = 7. x² da x ni o‘ziga ko‘paytir. Tenglamani Desmosda tekshirib, nuqtani o‘zing hisobla.","ru":"Чтобы найти y, подставь число вместо x. При y = 2x + 3 и x = 2 получим y = 2 × 2 + 3 = 7. x² означает x, умноженный на себя. Исследуй уравнение в Desmos и вычисли свою точку."},"prompt":{"en":"For y = 2x + 7, find y when x = 8.","uz":"y = 2x + 7 bo‘lsa, x = 8 da y ni top.","ru":"Для y = 2x + 7 найди y при x = 8."},"input":"number","graph":true}'::jsonb,'23') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
