insert into private.levelup_questions(id,idx,question,answer) values ('q28',28,'{"subject":"coding","title":{"en":"Windows shortcuts","uz":"Windows tugmalari","ru":"Сочетания Windows"},"lesson":{"en":"A shortcut combines keys to perform an action. Windows + E opens File Explorer. Windows + L locks your computer. Lock a shared school PC before leaving it.","uz":"Tugmalar birikmasi amalni tez bajaradi. Windows + E fayl boshqaruvchisini ochadi. Windows + L kompyuterni qulflaydi. Umumiy kompyuterdan ketayotganda uni qulflashni unutma.","ru":"Сочетание клавиш быстро выполняет действие. Windows + E открывает Проводник. Windows + L блокирует компьютер. Уходя от общего компьютера, блокируй его."},"prompt":{"en":"Which shortcut locks your PC?","uz":"Kompyuterni qaysi birikma qulflaydi?","ru":"Как заблокировать компьютер?"},"options":[{"value":"explorer","label":{"en":"Windows + E","uz":"Windows + E","ru":"Windows + E"}},{"value":"lock","label":{"en":"Windows + L","uz":"Windows + L","ru":"Windows + L"}},{"value":"print","label":{"en":"Ctrl + P","uz":"Ctrl + P","ru":"Ctrl + P"}}]}'::jsonb,'lock') on conflict(id) do update set idx=excluded.idx,question=excluded.question,answer=excluded.answer;
